	XtResizeWidget(model_init_form_view,width,new_height,
		       pref.border_width);

	if (model_init_popped_up)
	{
		/* In case the shell, which contains model_init_form_-	*/
		/* view and model_init_table, allready exists, is has	*/
		/* to be resized, too.					*/

	 n = 0;
